from query import parse_query

def test_repeats():
    assert parse_query('a=1&a=2') == {'a': ['1', '2']}
    assert parse_query('a=1&a=2&a=3') == {'a': ['1', '2', '3']}
    assert parse_query('a=1&b=2&a=3') == {'a': ['1', '3'], 'b': '2'}
def test_single():
    assert parse_query('a=1&b=2') == {'a': '1', 'b': '2'}
    assert parse_query('a=') == {'a': ''}
def test_bare_and_empty():
    assert parse_query('flag') == {'flag': ''}
    assert parse_query('flag&flag') == {'flag': ['', '']}
    assert parse_query('') == {}

